local function part(parent,name,size,cf,color,material,t) local p=Instance.new("Part"); p.Name=name; p.Size=size; p.CFrame=cf; p.Anchored=true; p.CanCollide=true; p.CanTouch=false; p.Color=color; p.Material=material or Enum.Material.Slate; p.Transparency=t or 0; p.TopSurface=Enum.SurfaceType.Smooth; p.BottomSurface=Enum.SurfaceType.Smooth; p.Parent=parent; return p end
local function label(a,title,sub,color) local g=Instance.new("BillboardGui"); g.Adornee=a; g.Size=UDim2.fromOffset(280,76); g.StudsOffsetWorldSpace=Vector3.new(0,7,0); g.AlwaysOnTop=true; g.MaxDistance=130; g.Parent=a; local x=Instance.new("TextLabel"); x.Size=UDim2.fromScale(1,1); x.BackgroundTransparency=1; x.Text=title.."\n"..sub; x.TextColor3=color; x.TextStrokeTransparency=.25; x.Font=Enum.Font.GothamBold; x.TextSize=15; x.TextWrapped=true; x.Parent=g end
local function groundY(x,z,f) local pa=RaycastParams.new(); pa.FilterType=Enum.RaycastFilterType.Include; pa.FilterDescendantsInstances={Terrain}; pa.IgnoreWater=true; local h=workspace:Raycast(Vector3.new(x,320,z),Vector3.new(0,-700,0),pa); return h and h.Position.Y or f end
local function spawnOf(id) if C.Zones[id] then return world:FindFirstChild(id.."Spawn") end; return zones:FindFirstChild(id.."_ExpansionSpawn") end
local function center(id) if C.Zones[id] then return C.Zones[id].Origin end; local s=spawnOf(id); return s and Vector3.new(s.Position.X,0,s.Position.Z) end
local names={A2="Val d'Astréa",S3="Sylvebrume",N4="Caps de Nacre",H2="Terres cendrées de Khar",O5="Forges d'Ormefer",V6="Profondeurs de l'Écho"}
Terrain:FillBlock(CFrame.new(0,-17,0),Vector3.new(900,50,2300),Enum.Material.Water); Terrain:FillBlock(CFrame.new(-500,8,0),Vector3.new(160,20,2100),Enum.Material.Sand); Terrain:FillBlock(CFrame.new(500,8,0),Vector3.new(160,20,2100),Enum.Material.Sand)
