local routes={{"A2_S3","A2","S3","Passage des Racines",Enum.Material.Ground,Color3.fromRGB(91,119,89)},{"A2_N4","A2","N4","Col des Embruns",Enum.Material.Slate,Color3.fromRGB(111,132,141)},{"H2_O5","H2","O5","Défilé des Scories",Enum.Material.Basalt,Color3.fromRGB(116,82,66)},{"H2_V6","H2","V6","Faille des Murmures",Enum.Material.Rock,Color3.fromRGB(104,87,125)}}
local function route(r) local a,b=center(r[2]),center(r[3]); if not a or not b then return end; local folder=Instance.new("Folder"); folder.Name=r[1]; folder.Parent=roads; local n=24; for i=0,n do local t=i/n; local x=a.X+(b.X-a.X)*t; local z=a.Z+(b.Z-a.Z)*t; local y=groundY(x,z,20+math.sin(t*math.pi)*4); Terrain:FillBall(Vector3.new(x,y-40,z),40,r[5]); if i%2==0 and i<n then local nt=(i+1)/n; local nx=a.X+(b.X-a.X)*nt; local nz=a.Z+(b.Z-a.Z)*nt; local d=Vector3.new(nx-x,0,nz-z); if d.Magnitude>.1 then part(folder,"Path",Vector3.new(17,1.1,d.Magnitude+10),CFrame.lookAt(Vector3.new(x,y+1.2,z),Vector3.new(nx,y+1.2,nz)),r[6],r[5]) end end end; local m=(a+b)*.5; local y=groundY(m.X,m.Z,24); local s=part(poi,r[1].."_Marker",Vector3.new(5,10,5),CFrame.new(m.X,y+5,m.Z),r[6],Enum.Material.Slate); label(s,r[4],names[r[2]].." ↔ "..names[r[3]],r[6]) end
for _,r in ipairs(routes) do route(r) end

